  ui_story_70000101_4_dialog_content = "<color=#e8d9bb>\"ตรวจสอบระบบพยุงชีพ... กำลังทำงาน คำเตือน: พิกัดความจุเต็ม จำเป็นต้องซ่อมบำรุง\"</color>",
