  ui_story_70000101_6_dialog_content = "<color=#e8d9bb>\"เกิดข้อผิดพลาด: ไม่พบเทมเพลตเอคโค่ ไม่สามารถเปิดใช้งานฟังก์ชันซ่อมบำรุงได้\"</color>",
  ui_story_70000101_7_dialog_content = "<color=#e8d9bb>\"เริ่มทำงานไม่สำเร็จ จำนวนครั้งที่ล้มเหลว: 1012\"</color>",
  ui_story_70000101_8_dialog_content = "<color=#e8d9bb>\"โปรดติดตั้งเทมเพลตเอคโค่เพื่อเข้าถึงฟังก์ชันการซ่อมบำรุง\"</color>",
  ui_story_70000101_9_dialog_content = "<color=#e8d9bb>\"คำเตือน: หากความสมบูรณ์ของส่วนประกอบลดต่ำกว่า 50% จะไม่สามารถเข้าถึงฟังก์ชันที่เกี่ยวข้องได้\"</color>",
