  ui_story_70000802_90_dialog_content = "แสดงว่าเธอ...",
  ui_story_70000802_91_dialog_content = "...ก็ยังไม่เคยเปลี่ยนเลยสินะ",
  ui_story_70000802_92_dialog_content = "ทั้งตัวเธอ แล้วก็อิลลูมินา",
  ui_story_70000802_93_dialog_content = "กรร!",
  ui_story_70000802_94_dialog_content = "ระวัง! เขามาทางนี้แล้ว!",
  ui_story_70000802_95_dialog_content = "จงโกรธแค้น และ... เติบโต",
  ui_story_70000802_96_dialog_content = "จงกลืนกินทุกสิ่ง... ในเขตแดนมืด!",
  ui_story_70000802_97_dialog_content = "กรร!",
  ui_story_70000802_98_dialog_content = "ได้เวลาจบเรื่องนี้แล้ว",
  ui_story_70000802_99_dialog_content = "ไวซ์ เตรียมตัวนะ!",
  ui_story_70000802_100_dialog_content = "ได้!",
  ui_story_70000902_1_dialog_content = "กรรร...",
  ui_story_70000902_2_dialog_content = "ขนาดอยู่ในสภาพนี้ก็ยังแพ้รึนี่?",
  ui_story_70000902_3_dialog_content = "สุดท้ายก็เป็นได้แค่<color=#FFB400>ตัวทดลองที่ล้มเหลว</color>เท่านั้นเอง",
  ui_story_70000902_4_dialog_content = "แต่ที่จริง แค่ขยับได้ก็ถือว่าสำเร็จเหนือความคาดหมายแล้วล่ะ",
  ui_story_70000902_5_dialog_content = "อย่างน้อยก็ยังพอมีค่าอะไรบ้าง",
  ui_story_70000902_6_dialog_content = "แต่น่าเสียดายที่ฉันไม่ได้มีเวลามากมายขนาดนั้น",
  ui_story_70000902_7_dialog_content = "อึก...!",
  ui_story_70000902_8_dialog_content = "พลังความมืด... กำลังรวมตัวกัน!",
  ui_story_70000902_9_dialog_content = "พลังความมืด... แข็งแกร่งเกินไป! ฉันไม่...",
  ui_story_70000902_10_dialog_content = "*แค่ก* ไม่ได้เจอกันแค่ไม่กี่ปี นักวิจัยอ่อนแออย่างเธอก็ต่อสู้เป็นแล้วสินะ",
  ui_story_70000902_11_dialog_content = "หุบปากซะ",
  ui_story_70000902_12_dialog_content = "สำหรับพวกอ่อนแอ คุกเข่ากับพื้นไปน่ะดีแล้ว",
  ui_story_70000902_13_dialog_content = "ส่วนนาย... รับพลังความมืดนี่ไปซะ แสดงให้ฉันเห็นหน่อยว่ายังพอมีค่าในวาระสุดท้าย!",
  ui_story_70000902_14_dialog_content = "กรร!",
  ui_story_70000902_15_dialog_content = "พวกอิคลิพไซท์...หายไปแล้ว!",
  ui_story_70000902_16_dialog_content = "อ๊ากกก! กรร!",
  ui_story_70000902_17_dialog_content = "พวกมัน...ร้องอย่างเจ็บปวด!",
  ui_story_70000902_18_dialog_content = "ฟอร์เซคินกำลังช่วงชิงพลังชีวิตของพวกมัน... ดูดพลังความมืดออกมา!",
  ui_story_70000902_19_dialog_content = "ถ้าถูกโจมตีด้วยพลังความมืดขนาดนี้ล่ะก็...",
