  ui_story_70000902_22_dialog_content = "...!",
  ui_story_70000902_23_dialog_content = "PlayerName ไปหาที่ซ่อนซะ!",
  ui_story_70000902_24_dialog_content = "ช้าไปแล้ว",
  ui_story_70000902_25_dialog_content = "(นี่เป็นพลังทำลายที่รุนแรงที่สุดเท่าที่ฉันเคยเห็น)",
  ui_story_70000902_26_dialog_content = "(พลังความมืดที่โอบล้อมทุกสิ่ง และความมืดมิดของดินแดนรัตติกาลนิรันดร์ กำลังโหมคลั่งเหมือนคลื่นทะเล ถาโถมใส่แผ่นดินเพื่อกวาดล้างทุกสิ่ง)",
  ui_story_70000902_27_dialog_content = "(ไวซ์กับฉันถูกตรึงกับพื้นด้วยแรงกดดันมหาศาล นอนแน่นิ่งไร้ทางสู้เมื่ออยู่ต่อหน้าพลังอันน่าหวาดกลัว)",
  ui_story_70000902_28_dialog_content = "(ฉันทำได้แค่เงยหน้าขึ้นมามองพลังความมืดกลืนกินพวกเรา)",
  ui_story_70000902_29_dialog_content = "และในความมืดมิดไร้ขอบเขตนั้น...",
  ui_story_70000902_30_dialog_content = "ฉันก็พลันเห็น<color=#FFB400>แสงสว่าง</color>",
  ui_story_70000902_31_dialog_content = "ไม่ ฉันไม่ยอมให้คุณได้ในสิ่งที่คุณต้องการ!",
  ui_story_70000902_32_dialog_content = "คุณไรน์ฮาร์ต!?",
  ui_story_70000902_33_dialog_content = "(ท่ามกลางความมืดมิดอันเป็นนิรันดร์ แสงสว่างอันริบหรี่อาจดับลงเมื่อไหร่ก็ได้...)",
  ui_story_70000902_34_dialog_content = "(แต่มันก็ยังยืนหยัดท้าทายความมืด แผ่ขยายความสว่างออกไป)",
  ui_story_70000902_35_dialog_content = "(เหมือนดวงอาทิตย์ยามรุ่งสางบนขอบฟ้า เป็นสัญญาณบอกการมาถึงของวันใหม่)",
  ui_story_70000902_36_dialog_content = "ก็แค่... พลังความมืดกระจอก ๆ",
  ui_story_70000902_37_dialog_content = "และฉันแบกความงดงามของอิลลูมินาไว้บนบ่า!",
  ui_story_70000902_38_dialog_content = "แม้ท้องฟ้าจะถล่มลงมา ฉันก็จะปกป้องอิลลูมินาให้ได้!",
  ui_story_70000902_39_dialog_content = "(ความมืดค่อย ๆ ถูกขับไล่ไปทีละน้อย...)",
  ui_story_70000902_40_dialog_content = "(แสงสว่างทิ่มแทงทะลุเมฆหมอก)",
  ui_story_70000902_41_dialog_content = "อึก!",
  ui_story_70000902_42_dialog_content = "...!",
  ui_story_70000902_43_dialog_content = "คุณไรน์ฮาร์ต!",
  ui_story_70000902_44_dialog_content = "ละทิ้งการป้องกันทั้งหมดเพื่อการโจมตีเต็มรูปแบบ... งั้นรึ?",
  ui_story_70000902_45_dialog_content = "แต่ถึงอย่างนั้น การโจมตีส่วนใหญ่ก็ปัดป้องได้ไม่ยาก...",
  ui_story_70000902_46_dialog_content = "หึหึ... โง่อะไรอย่างนี้",
  ui_story_70000902_47_dialog_content = "ทั้งโง่...แล้วก็บ้า",
  ui_story_70000902_48_dialog_content = "พลังระดับนี้เป็นไปตามความคาดหวังของการทดลอง",
  ui_story_70000902_49_dialog_content = "ด้วยพลังความมืดระดับนี้ ออโรเรียนทั่วไปคงจะเสียสติไปแล้ว",
  ui_story_70000902_50_dialog_content = "ก็สมกับเป็นเธอแล้วล่ะ",
  ui_story_70000902_51_dialog_content = "สมแล้วที่เป็นถึง \"สัตว์ประหลาด\" ที่รอดมาจากบึงโคลนดูดได้",
  ui_story_70000902_52_dialog_content = "คนพวกนั้น \"สั่งสอน\" เธอมาดีจริง ๆ",
  ui_story_70000902_53_dialog_content = "หึ เธอก็เหมือนกัน",
  ui_story_70000902_54_dialog_content = "แม้จะมีฝีมือร้ายกาจขนาดนี้ แต่กลับหยุดหาหนทางพัฒนา มองตัวเองเป็นแค่ผู้กล้าในนิทานของเด็ก ๆ...",
  ui_story_70000902_55_dialog_content = "แถมดูเธอยัง... สนุกกับมันมาก ๆ ซะด้วย",
  ui_story_70000902_56_dialog_content = "เพราะนั่นเป็นความฝันของเรา... ไม่ใช่หรือไง?",
  ui_story_70000902_57_dialog_content = "ได้เป็นจอมทัพแห่งอิลลูมินา นำผู้คนของอิลลูมินาไปสู่โลกที่ดีกว่า",
  ui_story_70000902_58_dialog_content = "เพื่ออิลลูมินา เพื่อทุก ๆ คน...",
  ui_story_70000902_59_dialog_content = "ช่างไร้เดียงสาจริง ๆ แล้วคนพวกนั้นทำอะไรให้เธอบ้าง? นอกจากเห็นเธอเป็นของตาย และขอให้เธอปกป้องไม่จบไม่สิ้น",
  ui_story_70000902_60_dialog_content = "ในสายตาของพวกนั้น เธอก็เป็นแค่สัญลักษณ์ พร้อมที่จะถูกเปลี่ยนออกและทิ้งขว้างได้ไม่ยากเมื่อหมดประโยชน์",
  ui_story_70000902_61_dialog_content = "ความเป็นจริงก็คือ ตัวเธอมันก็ไม่ต่างจากสัตว์ทดลอง",
  ui_story_70000902_62_dialog_content = "นักวิจัยน่ะ สนใจแต่ข้อมูลที่ได้จากตัวทดลองเท่านั้น",
  ui_story_70000902_63_dialog_content = "และคนพวกนั้นก็สนใจแค่... ภาพลักษณ์ที่ดูแข็งแกร่ง ซึ่งพวกเขาก็ไม่สนหรอก ว่าใครจะเป็นคนนำเสนอภาพลักษณ์นั้น",
  ui_story_70000902_64_dialog_content = "หึหึ...",
  ui_story_70000902_65_dialog_content = "ฮ่าฮ่าฮ่า!",
  ui_story_70000902_66_dialog_content = "ฟอร์เซคิน... ไม่สิ ดีเนียร์...",
  ui_story_70000902_67_dialog_content = "เธอเองก็คุยเก่งขึ้นเยอะนะ",
  ui_story_70000902_68_dialog_content = "ฉันยังจำได้เลย สมัยที่เธอเอาแต่ขังตัวอยู่ในแล็บแล้วก็ยุ่งกับการทดลอง",
  ui_story_70000902_69_dialog_content = "ไม่ว่าฉันจะพูดยังไง แต่เธอก็คิดแต่จะพิสูจน์ให้โลกได้เห็นว่าเธอน่ะเก่งที่สุด",
  ui_story_70000902_70_dialog_content = "...",
