  ui_story_70000902_72_dialog_content = "และฉันเองก็เหมือนเธอนั่นแหละ ฉันคือจอมทัพแห่งอิลลูมินา หน้าที่ของฉันคือการปกป้องอิลลูมินาและผู้คน มันก็เท่านั้น",
  ui_story_70000902_73_dialog_content = "พวกนั้นจะเห็นฉันเป็นอะไร ฉันไม่สนอยู่แล้ว",
