  ui_story_70000902_104_dialog_content = "ผมสัมผัสได้ว่ามีอิคลิพไซท์ทั้งกองทัพมุ่งหน้ามาหาเรา! อีกเดี๋ยวมันก็จะถึงแล้ว!",
