  ui_story_70001001_16_dialog_content = "<color=#e8d9bb>\"กำลังสแกนข้อมูล... สแกนเสร็จเรียบร้อย\"</color>",
  ui_story_70001001_17_dialog_content = "<color=#e8d9bb>\"ผลการสแกน: พบโมดูลซ่อมเทมเพลตเอคโค่พร้อมข้อมูลอัปเกรด\"</color>",
  ui_story_70001001_18_dialog_content = "<color=#e8d9bb>\"ติดตั้งโมดูลซ่อมเทมเพลตเอคโค่เพื่ออัปเกรดระบบพยุงชีพให้เป็นระบบรักษาฉุกเฉิน\"</color>",
  ui_story_70001001_19_option_content = "โซรอซ?",
