  ui_story_70001001_24_dialog_content = "<color=#e8d9bb>\"ตรวจพบโมดูลซ่อมเทมเพลตเอคโค่\"</color>",
  ui_story_70001001_25_dialog_content = "<color=#e8d9bb>\"กำลังเชื่อมต่อ... เชื่อมต่อเสร็จเรียบร้อย\"</color>",
  ui_story_70001001_26_dialog_content = "<color=#e8d9bb>\"พิจารณาลำดับความสำคัญของระบบ... เสร็จเรียบร้อย\"</color>",
  ui_story_70001001_27_dialog_content = "<color=#e8d9bb>\"พบข้อมูลอัปเกรดระบบพยุงชีพ กำลังเริ่มการอัปเกรด\"</color>",
