  ui_story_70001001_40_dialog_content = "ระบบป้อนคำสั่งด้วยเสียงเมื่อกี้... โซรอซคงรู้ว่าเราต้องการความช่วยเหลือ มันก็เลยทำงาน...",
  ui_story_70001001_41_dialog_content = "อื้ม...",
