  ui_story_70001001_44_dialog_content = "ได้เลย เดี๋ยวฉันช่วยอีกแรง",
  ui_story_70001001_45_dialog_content = "<color=#e8d9bb>\"เริ่มขั้นตอนการซ่อมเทมเพลตเอคโค่ต่อจากที่ค้างไว้\"</color>",
  ui_story_70001001_46_dialog_content = "<color=#e8d9bb>\"ขั้นตอนที่ 1: โปรดติดตั้งปลั๊กอินฐานข้อมูลมาตรฐานสำหรับจิตสำนึกของโคลอสซัส\"</color>",
