  ui_story_70001001_50_dialog_content = "เอ่อ... มีแค่อันนี้อันเดียว...",
  ui_story_70001001_51_dialog_content = "โซรอซ ปลั๊กอินฐานข้อมูลคืออะไรเหรอ?",
  ui_story_70001001_52_dialog_content = "<color=#e8d9bb>\"กำลังค้นหาข้อมูลเกี่ยวกับปลั๊กอินฐานข้อมูลมาตรฐานสำหรับจิตสำนึกของโคลอสซัส... การค้นหาเสร็จเรียบร้อย\"</color>",
  ui_story_70001001_53_dialog_content = "<color=#e8d9bb>\"คำตอบ: ฐานข้อมูลมาตรฐานสำหรับจิตสำนึกของโคลอสซัส เป็นแม่แบบข้อมูลสำหรับมอบจิตสำนึกให้กับโคลอสซัส\"</color>",
  ui_story_70001001_54_dialog_content = "<color=#e8d9bb>\"จำนวนโมดูลที่มีในปัจจุบัน: 0\"</color>",
  ui_story_70001001_55_dialog_content = "<color=#e8d9bb>\"คำแนะนำ: ปลั๊กอินฐานข้อมูลมาตรฐานสำหรับจิตสำนึกของโคลอสซัส สามารถพบได้ที่ฐานซ่อมบำรุงโคลอสซัส\"</color>",
  ui_story_70001001_56_dialog_content = "<color=#e8d9bb>\"กำลังค้นหาตำแหน่งฐานซ่อมบำรุงโคลอสซัสที่ใกล้ที่สุด... การค้นหาเสร็จเรียบร้อย\"</color>",
  ui_story_70001001_57_dialog_content = "<color=#e8d9bb>\"เป้าหมายที่ตรวจพบ: อีราเวล\"</color>",
  ui_story_70001001_58_dialog_content = "อีราเวล...!?",
  ui_story_70001001_59_dialog_content = "ยังมีฐานอยู่ใน Eraveil!?",
  ui_story_70001001_60_dialog_content = "ทำไมฉันไม่เคยรู้เรื่องนี้เลย...",
  ui_story_70001001_61_dialog_content = "<color=#e8d9bb>\"หมายเหตุ: หากไม่สามารถติดตั้งปลั๊กอินได้ โมดูลซ่อมแซมเทมเพลตเอคโค่จะเข้าสู่โหมดแสตนด์บาย\"</color>",
  ui_story_70001001_62_dialog_content = "เข้าสู่โหมดแสตนด์บาย...",
  ui_story_70001001_63_dialog_content = "<color=#e8d9bb>\"โมดูลซ่อมเทมเพลตเอคโค่ของโซรอซกำลังเข้าสู่โหมดแสตนด์บาย\"</color>",
  ui_story_70001001_64_dialog_content = "ถ้าเรากลับถึงอีราเวลเมื่อไหร่ ฉันจะต้องหา<color=#FFB400>ฐานซ่อมบำรุงโคลอสซัส</color>ให้เจอ",
